import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] inputLine = sc.nextLine().split(" ");
        int base = Integer.parseInt(inputLine[0]);
        int num = Integer.parseInt(inputLine[1]);
        boolean isValid = true;
        List<Integer> digitsList = new ArrayList<>();
        while (num != 0) {
            digitsList.add(0, num % base);
            num /= base;
        }
        for (int i = 0; i < digitsList.size(); i++) {
            int d = digitsList.get(i);
            if (d == 0 || d == 1) continue;
            if (d == base - 1) {
                int j = i + 1;
                while (j < digitsList.size()) {
                    int val = digitsList.get(j);
                    if (val == base - 1) {
                        digitsList.set(j, 0);
                    } else {
                        digitsList.set(j, val + 1);
                        break;
                    }
                    j++;
                }
            } else {
                isValid = false;
                break;
            }
        }
        System.out.println(isValid ? "YES" : "NO");
    }
}
