#include <iostream>
#include <vector>
#include <string>
#include <sstream>

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::istringstream iss(line);
    int base, num;
    iss >> base >> num;

    bool isValid = true;
    std::vector<int> digitsList;

    // Convert number to base representation
    while (num != 0) {
        digitsList.insert(digitsList.begin(), num % base);
        num /= base;
    }

    // Process the digits
    for (size_t i = 0; i < digitsList.size(); ++i) {
        int d = digitsList[i];
        if (d == 0 || d == 1) continue;
        if (d == base - 1) {
            size_t j = i + 1;
            while (j < digitsList.size()) {
                int val = digitsList[j];
                if (val == base - 1) {
                    digitsList[j] = 0;
                } else {
                    digitsList[j] = val + 1;
                    break;
                }
                ++j;
            }
        } else {
            isValid = false;
            break;
        }
    }

    std::cout << (isValid ? "YES" : "NO") << std::endl;

    return 0;
}
